const id = $json.params.id;

const isUuid =
    typeof id === 'string' &&
    /^[0-9a-fA-F]{8}\b-[0-9a-fA-F]{4}\b-[0-9a-fA-F]{4}\b-[0-9a-fA-F]{4}\b-[0-9a-fA-F]{12}$/.test(id);

return { 
  id, 
  valido: isUuid
}

const body = $input.first().json.body ?? {};

const { cliente_id, titulo, descricao, prioridade } = body;

const erros = [];

const PRIORIDADES_PERMITIDAS = ["baixa", "media", "alta"]

const isUuid = (value) =>
    typeof value === 'string' &&
    /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$/.test(value);

if (!cliente_id) {
    erros.push('cliente_id é obrigatório');
} else if (!isUuid(cliente_id)) {
    erros.push('cliente_id inválido');
}

if (!titulo) {
    erros.push('título é obrigatório');
} else if (typeof titulo !== 'string' || titulo.trim().length < 2) {
    erros.push('título inválido');
}

if (!descricao) {
    erros.push('descrição é obrigatória');
} else if (typeof descricao !== 'string' || descricao.trim().length < 8) {
    erros.push('descrição deve ter pelo menos 8 caracteres');
}

if (prioridade && !PRIORIDADES_PERMITIDAS.includes(prioridade)) {
  erros.push("prioridade inválida")
}

return {
  cliente_id,
  titulo,
  descricao,
  prioridade: prioridade ?? "media",
  erros,
  valido: erros.length === 0,
  trace_id: $execution.id,
  started_at: Date.now(),
}

const id = $json.params.id;

const isUuid =
    typeof id === 'string' &&
    /^[0-9a-fA-F]{8}\b-[0-9a-fA-F]{4}\b-[0-9a-fA-F]{4}\b-[0-9a-fA-F]{4}\b-[0-9a-fA-F]{12}$/.test(id);

return { 
  id, 
  valido: isUuid
}

const query = $json.query ?? {};

const STATUS_VALIDOS = [
  'aberto',
  'em_atendimento',
  'aguardando_cliente',
  'resolvido',
  'cancelado'
];

const PRIORIDADES_VALIDAS = [
  'baixa',
  'media',
  'alta'
];

const status = query.status?.trim() || null;
const prioridade = query.prioridade?.trim() || null;

const erros = [];

if (status && !STATUS_VALIDOS.includes(status)) {
  erros.push('status inválido');
}

if (prioridade && !PRIORIDADES_VALIDAS.includes(prioridade)) {
  erros.push('prioridade inválida');
}

if (erros.length > 0) {
  return [{
    json: {
      valido: false,
      erros
    }
  }];
}

let sql = `
  select
    t.*,
    c.nome as cliente_nome
  from tickets t
  join clientes c on c.id = t.cliente_id
  where 1=1
`;

const params = [];

if (status) {
  params.push(status);
  sql += ` and t.status = $${params.length}`;
}

if (prioridade) {
  params.push(prioridade);
  sql += ` and t.prioridade = $${params.length}`;
}

sql += ' order by t.criado_em desc';

return {
  valido: true,
  sql,
  params
}

const id = $json.params.id;
const { status } = $json.body ?? {};
const erros = [];

const STATUS_VALIDOS = ['aberto', 'em_atendimento', 'aguardando_cliente', 'resolvido', 'cancelado'];

const isUuid =
    typeof id === 'string' &&
    /^[0-9a-fA-F]{8}\b-[0-9a-fA-F]{4}\b-[0-9a-fA-F]{4}\b-[0-9a-fA-F]{4}\b-[0-9a-fA-F]{12}$/.test(id);

if (!isUuid) erros.push("ID inválido")

if (!status) erros.push('status é obrigatório');
else if (!STATUS_VALIDOS.includes(status)) erros.push('status inválido');

return { 
  id, 
  status, 
  erros, 
  valido: erros.length === 0 
}

const body = $json.body ?? {};
const params = $json.params ?? {};

const { mensagem } = body;
const { id } = params;

const erros = [];

const isUuid = (value) =>
  typeof value === 'string' &&
  /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$/.test(
    value,
  );

if (id === undefined || id === null || id === '') {
  erros.push('ID do ticket é obrigatório');
} else if (typeof id !== 'string') {
  erros.push('ID do ticket deve ser um texto');
} else if (!isUuid(id.trim())) {
  erros.push('ID do ticket deve ser um UUID válido');
}

if (
  mensagem === undefined ||
  mensagem === null ||
  mensagem === ''
) {
  erros.push('mensagem é obrigatória');
} else if (typeof mensagem !== 'string') {
  erros.push('mensagem deve ser um texto');
} else if (mensagem.trim().length < 5) {
  erros.push('mensagem deve ter pelo menos 5 caracteres');
}

return {
  id:
    typeof id === 'string'
      ? id.trim()
      : id,

  mensagem:
    typeof mensagem === 'string'
      ? mensagem.trim()
      : mensagem,

  erros,
  valido: erros.length === 0,
  trace_id: $execution.id,
  started_at: Date.now(),
};
